import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.autotune(
    configs=[
        triton.Config(
            {"BLOCK_SIZE": 32},
        ),
    ],
    key=["output_length"],
)
@triton.jit
def maxpool1d_kernel(
    input_ptr,
    output_ptr,
    seq_length,
    output_length,
    num_channels,
    stride_b,
    stride_c,
    stride_out_b,
    stride_out_c,
    KERNEL_SIZE: tl.constexpr,
    STRIDE: tl.constexpr,
    PADDING: tl.constexpr,
    DILATION: tl.constexpr,
    BLOCK_SIZE: tl.constexpr,
):
    pid_bc = tl.program_id(0)
    pid_o = tl.program_id(1)

    b = pid_bc // num_channels
    c = pid_bc % num_channels

    o_start = pid_o * BLOCK_SIZE
    o_offsets = o_start + tl.arange(0, BLOCK_SIZE)
    o_mask = o_offsets < output_length

    base_in = input_ptr + b * stride_b + c * stride_c
    running_max = tl.full([BLOCK_SIZE], value=-float("inf"), dtype=tl.float32)

    for k in range(KERNEL_SIZE):
        inp_idx = o_offsets * STRIDE + k * DILATION - PADDING
        valid = (inp_idx >= 0) & (inp_idx < seq_length) & o_mask
        vals = tl.load(base_in + inp_idx, mask=valid, other=-float("inf"))
        running_max = tl.maximum(running_max, vals.to(tl.float32))

    base_out = output_ptr + b * stride_out_b + c * stride_out_c
    tl.store(base_out + o_offsets, running_max.to(tl.bfloat16), mask=o_mask)


class Model(nn.Module):
    def __init__(
        self,
        kernel_size: int,
        stride: int = None,
        padding: int = 0,
        dilation: int = 1,
        return_indices: bool = False,
    ):
        super(Model, self).__init__()
        self.kernel_size = kernel_size
        self.stride = stride if stride is not None else kernel_size
        self.padding = padding
        self.dilation = dilation

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        device = x.device
        B, C, L = x.shape
        x = x.to(device).contiguous()

        output_length = (
            L + 2 * self.padding - self.dilation * (self.kernel_size - 1) - 1
        ) // self.stride + 1
        output = torch.empty((B, C, output_length), device=device, dtype=x.dtype)

        grid = lambda META: (B * C, triton.cdiv(output_length, META["BLOCK_SIZE"]))
        maxpool1d_kernel[grid](
            x,
            output,
            L,
            output_length,
            C,
            x.stride(0),
            x.stride(1),
            output.stride(0),
            output.stride(1),
            KERNEL_SIZE=self.kernel_size,
            STRIDE=self.stride,
            PADDING=self.padding,
            DILATION=self.dilation,
        )
        return output
